//! Recompiled programs (docs/recompiler.md). Each one is a crate of its own,
//! generated by `remodel recomp` under out/recomp/; a generated registry
//! crate lists them and the front end hands that list to [`register`] at
//! startup. Without it the list is empty and every program runs on the
//! interpreters.

use crate::Block;
use adsp2106x::cpu::{Sharc, Step as SharcStep};
use mb86235::cpu::{Step, Tgp};
use std::sync::OnceLock;

pub use crate::bus::TgpExt;
pub use crate::geo::{GeoExt, SharcGeoBus};
pub use crate::sharc::CoproBus as SharcCoproBus;

/// A recompiled copro (TGP) program's `step`.
pub type CoproStep = for<'a> fn(&mut Tgp, &mut TgpExt<'a>) -> Step;
/// A recompiled geometrizer program's `step`.
pub type GeoStep = for<'a> fn(&mut Tgp, &mut GeoExt<'a>) -> Step;

/// A recompiled ADSP-21062 program's `run` on the 2B copro: instructions
/// as `Sharc::run_bus` runs them.
pub type SharcCoproRun = for<'a> fn(&mut Sharc, &mut SharcCoproBus<'a>) -> SharcStep;
/// The same on the 2B geometrizer.
pub type SharcGeoRun = for<'a> fn(&mut Sharc, &mut SharcGeoBus<'a>) -> SharcStep;

/// A recompiled i960 program, keyed by `program_hash`.
pub struct I960Program {
    pub hash: u64,
    /// Its blocks by start address.
    pub blocks: fn() -> Vec<(u32, Block)>,
}

/// A recompiled MB86235 program, keyed by `mb86235::cpu::program_hash`.
/// The same program can run on the copro or the geometrizer.
pub struct TgpProgram {
    pub hash: u64,
    pub copro: CoproStep,
    pub geo: GeoStep,
}

/// A recompiled ADSP-21062 program, named by
/// `adsp2106x::cpu::code_hash` of the words it has code for and found by
/// those words being in a SHARC's memory (uploads with the same code and
/// different data share one), compiled for the processor (copro or
/// geometrizer) it was captured on, or both.
pub struct SharcProgram {
    pub hash: u64,
    /// The words it was compiled from, as 48-bit words from 0x20000 (zero
    /// where none was compiled).
    pub image: &'static [u64],
    /// The compiled words' addresses.
    pub words: &'static [u32],
    pub copro: Option<SharcCoproRun>,
    pub geo: Option<SharcGeoRun>,
}

/// Everything a build has recompiled code for.
pub struct Programs {
    pub i960: &'static [I960Program],
    pub tgp: &'static [TgpProgram],
    pub sharc: &'static [SharcProgram],
}

static PROGRAMS: OnceLock<Programs> = OnceLock::new();
const NONE: Programs = Programs { i960: &[], tgp: &[], sharc: &[] };

/// Install the build's recompiled programs. Call it once, before the first
/// `Machine`; later calls are ignored.
pub fn register(programs: Programs) {
    let _ = PROGRAMS.set(programs);
}

fn programs() -> &'static Programs {
    PROGRAMS.get().unwrap_or(&NONE)
}

/// How many recompiled programs (i960, MB86235 and ADSP-21062) are
/// registered.
pub fn count() -> usize {
    programs().i960.len() + programs().tgp.len() + programs().sharc.len()
}

/// The recompiled i960 blocks for a program ROM image, if registered.
pub fn i960_blocks(hash: u64) -> Option<Vec<(u32, Block)>> {
    programs().i960.iter().find(|p| p.hash == hash).map(|p| (p.blocks)())
}

/// The recompiled copro `step` for an MB86235 program, if registered.
#[inline]
pub fn copro(hash: u64) -> Option<CoproStep> {
    programs().tgp.iter().find(|p| p.hash == hash).map(|p| p.copro)
}

/// The recompiled geometrizer `step` for an MB86235 program, if registered.
pub fn geo(hash: u64) -> Option<GeoStep> {
    programs().tgp.iter().find(|p| p.hash == hash).map(|p| p.geo)
}

/// Which SHARC a program runs on.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SharcRole {
    Copro,
    Geo,
}

/// The recompiled program for what a SHARC holds, if registered for its
/// `role`: one whose compiled words are all in memory as they were
/// compiled (the one with the most, should several be). Attaches it to
/// `cpu` (see `Sharc::watch_code`); detaches when there is none. The
/// words are what the code was compiled from: data elsewhere in the image
/// (or changed since, as after a save state load) doesn't matter, since
/// recompiled code reads memory as it runs.
pub fn attach_sharc(cpu: &mut Sharc, role: SharcRole) -> Option<&'static SharcProgram> {
    let has_role = |p: &SharcProgram| match role {
        SharcRole::Copro => p.copro.is_some(),
        SharcRole::Geo => p.geo.is_some(),
    };
    let found = programs()
        .sharc
        .iter()
        .filter(|p| has_role(p))
        .filter(|p| p.words.iter().all(|&a| p.image.get((a - 0x2_0000) as usize) == Some(&cpu.mem.read48(a))))
        .max_by_key(|p| p.words.len());
    match found {
        Some(p) => cpu.watch_code(p.words, p.image),
        None => cpu.watch_code(&[], &[]),
    }
    found
}
